__global__ void fused_silu_mul_inplace_kernel(
    scalar_t* __restrict__ gate,
    const scalar_t* __restrict__ up,
    int N
) {
    int base_idx = (blockIdx.x * blockDim.x + threadIdx.x) * 8;

    if (base_idx >= N) return;

    // Load 8 elements at once
    float4 gv = reinterpret_cast<const float4*>(gate)[(blockIdx.x * blockDim.x + threadIdx.x)];
    float4 uv = reinterpret_cast<const float4*>(up)[(blockIdx.x * blockDim.x + threadIdx.x)];

    const scalar_t* g_vals = reinterpret_cast<const scalar_t*>(&gv);
    const scalar_t* u_vals = reinterpret_cast<const scalar_t*>(&uv);

    float4 ov;
    scalar_t* o_vals = reinterpret_cast<scalar_t*>(&ov);

    #pragma unroll
    for (int j = 0; j < 8; j++) {
        int idx = base_idx + j;
        if (idx < N) {
            float g = static_cast<float>(g_vals[j]);
            float u = static_cast<float>(u_vals[j]);
            float silu_g = g / (1.0f + expf(-g));
            o_vals[j] = static_cast<scalar_t>(silu_g * u);
        }
    }

    reinterpret_cast<float4*>(gate)[(blockIdx.x * blockDim.x + threadIdx.x)] = ov;
}
